import{I as p,o as t,c as o,b6 as n,J as r,w as h,j as s,a as l}from"./chunks/framework.COUcLbTA.js";const g=JSON.parse('{"title":"Jobs to Be Done으로 사용자가 진짜 완료하고 싶은 일 찾기","description":"제로 베이스 독자를 위한 Jobs to Be Done 입문 글입니다. 사용자는 기능을 사는 것이 아니라 특정 장면에서 제품을 \\"고용\\"해 진전을 완성한다는 관점을 이해하고, JTBD로 제품 방향, 인터뷰 질문, AI 프롬프트를 분해하는 법을 배웁니다.","frontmatter":{"title":"Jobs to Be Done으로 사용자가 진짜 완료하고 싶은 일 찾기","description":"제로 베이스 독자를 위한 Jobs to Be Done 입문 글입니다. 사용자는 기능을 사는 것이 아니라 특정 장면에서 제품을 \\"고용\\"해 진전을 완성한다는 관점을 이해하고, JTBD로 제품 방향, 인터뷰 질문, AI 프롬프트를 분해하는 법을 배웁니다."},"headers":[],"relativePath":"ko-kr/stage-1/appendix-jobs-to-be-done/index.md","filePath":"ko-kr/stage-1/appendix-jobs-to-be-done/index.md"}'),d={name:"ko-kr/stage-1/appendix-jobs-to-be-done/index.md"},k=Object.assign(d,{setup(c){const i="약 <strong>1.5시간</strong>";return(b,a)=>{const e=p("ChapterIntroduction");return t(),o("div",null,[a[1]||(a[1]=n('<h1 id="jobs-to-be-done으로-사용자가-진짜-완료하고-싶은-일-찾기" tabindex="-1">Jobs to Be Done으로 사용자가 진짜 완료하고 싶은 일 찾기 <a class="header-anchor" href="#jobs-to-be-done으로-사용자가-진짜-완료하고-싶은-일-찾기" aria-label="Permalink to “Jobs to Be Done으로 사용자가 진짜 완료하고 싶은 일 찾기”">​</a></h1><p><a id="top-jtbd"></a></p><h2 id="본-장-안내" tabindex="-1">본 장 안내 <a class="header-anchor" href="#본-장-안내" aria-label="Permalink to “본 장 안내”">​</a></h2>',3)),r(e,{duration:i,tags:["JTBD","사용자 수요","제품 사고","수요 인사이트"],coreOutput:"실제 수요에 더 가까운 JTBD 문장 1개",expectedOutput:"흐릿한 아이디어를 더 구체적인 사용자 장면과 MVP 방향으로 수렴할 수 있음"},{default:h(()=>[...a[0]||(a[0]=[s("p",null,'많은 사람이 처음 제품을 만들 때 가장 쉽게 하는 실수는 모든 주의를 "내가 어떤 기능을 만들 것인가"에 두는 것입니다. 다른 제품에 지능형 분류가 있으면 나도 넣고 싶고, 자동 요약이 있으면 나도 붙이고 싶고, 다른 사람이 Agent, 멀티모달, 워크플로우를 만들면 나도 빼면 안 될 것 같습니다.',-1),s("p",null,'하지만 현실에서 사용자는 "이 기능 이름이 멋있어서" 제품을 쓰는 경우가 드뭅니다. 그들은 더 자주 어떤 구체적인 순간에 어떤 일을 앞으로 밀고 싶어 합니다. 그래서 일시적으로 도구, 서비스, 심지어 사람을 "고용"해 그 한 단계를 완성합니다.',-1),s("p",null,[l("이것이 바로 "),s("strong",null,"Jobs to Be Done(JTBD)"),l(" 방법이 우리에게 상기시키는 것입니다. "),s("strong",null,"사용자는 기능 자체를 구매하는 것이 아니라, 자신이 어떤 진전을 완성하도록 도와주는 해결책을 고용합니다.")],-1),s("p",null,"이 글은 가능한 한 쉬운 언어로 JTBD를 처음부터 이해하게 하고, AI 애플리케이션을 만들 때 바로 쓸 수 있는 분석 도구로 바꾸도록 안내합니다.",-1)])]),_:1}),a[2]||(a[2]=n(`<div class="info custom-block"><p class="custom-block-title">최소 SOP</p><p><strong>목적</strong>: 읽고 나면 흐릿한 아이디어를, 기능 이름만 잔뜩 있는 상태가 아니라 실제 사용자 장면이 있는 수요 한 문장으로 수렴하는 법을 더 명확히 알게 됩니다.</p><p><strong>행동 항목</strong>: 흐릿한 아이디어 1문장을 쓰고, 잠재 사용자 3명에게 &quot;최근 한 번은 어떻게 처리했는지&quot;를 묻고, JTBD 문장 1개로 정리합니다.</p><p><strong>결과</strong>: 더 명확한 수요 가설을 얻고, 첫 버전에서 무엇을 먼저 해결해야 하는지 알게 됩니다.</p><p><strong>키워드 이동</strong>: <a href="#jtbd-what">JTBD란 무엇인가</a> · <a href="#jtbd-formula">한 문장 공식</a> · <a href="#jtbd-ai">AI는 어떻게 도와줄 수 있나</a></p></div><h2 id="다음-내용을-배우게-됩니다" tabindex="-1">다음 내용을 배우게 됩니다 <a class="header-anchor" href="#다음-내용을-배우게-됩니다" aria-label="Permalink to “다음 내용을 배우게 됩니다”">​</a></h2><ol><li>Jobs to Be Done이 무엇이고, 왜 &quot;기능 브레인스토밍&quot;보다 실제 수요에 더 가까운지</li><li>&quot;사용자가 원한다고 말한 기능&quot;과 &quot;사용자가 진짜 완료하고 싶은 일&quot;을 구분하는 법</li><li>간단한 템플릿으로 흐릿한 아이디어를 장면, 트리거, 장애물, 성공 기준으로 분해하는 법</li><li>JTBD를 AI 제품, 인터뷰 질문, 프롬프트 정리에 활용하는 법</li></ol><p><a id="jtbd-what"></a></p><h2 id="_1-jobs-to-be-done이란-무엇인가" tabindex="-1"><a href="#top-jtbd">1. Jobs to Be Done이란 무엇인가</a> <a class="header-anchor" href="#_1-jobs-to-be-done이란-무엇인가" aria-label="Permalink to “1. Jobs to Be Done이란 무엇인가”">​</a></h2><p>Jobs to Be Done은 보통 <strong>JTBD</strong>라고 줄여 부릅니다. 그 핵심 생각은 Clayton Christensen 팀이 널리 알린 고전적인 표현과 관련 있습니다. <strong>사용자는 어떤 제품을 &quot;고용&quot;해 하나의 일을 완성한다</strong>는 것입니다.</p><p>여기서 말하는 &quot;일&quot;은 할 일 목록의 표면적 동작이 아니라, 사용자가 자신의 상태에서 일으키고 싶은 어떤 <strong>진전</strong>입니다. 예를 들면 다음과 같습니다.</p><ul><li>&quot;AI 회의록 도구가 필요하다&quot;가 아니라, &quot;회의 후 10분 안에 핵심, 할 일, 담당자를 정리해서 기억에 의존해 메모를 보충하지 않고 싶다&quot;</li><li>&quot;가계부 App이 필요하다&quot;가 아니라, &quot;돈이 정확히 어디로 갔는지 알고 싶어서 월말에 다시 불안해지고 싶지 않다&quot;</li><li>&quot;이력서 최적화기가 필요하다&quot;가 아니라, &quot;그럴듯한 이력서를 더 확신 있게 제출하고 싶고, 매번 지원할 때마다 내가 너무 못 쓴 건 아닌지 의심하고 싶지 않다&quot;</li></ul><p>따라서 <strong>JTBD가 주목하는 것은 제품이 어떻게 생겼는지가 아니라, 사용자가 왜 이 순간 그것을 필요로 하는가입니다.</strong></p><p>그래서 겉으로는 서로 달라 보이는 제품도 실제로는 같은 job을 두고 경쟁할 수 있습니다. 사용자가 &quot;출근길을 덜 지루하게 보내고 싶다&quot;면 고용할 수 있는 대상은 숏폼 영상, 팟캐스트, 게임, 채팅, 심지어 잠깐 조는 것일 수 있습니다. 사용자가 &quot;긴 PDF를 빠르게 이해하고 싶다&quot;면 고용할 수 있는 대상은 AI 요약 도구, 인턴, 동료, 억지로 직접 읽기, 또는 일단 안 읽기일 수 있습니다.</p><p>이 관점으로 문제를 보면 진짜 경쟁자는 대개 &quot;당신과 비슷하게 생긴 다른 App&quot;만이 아니라, <strong>사용자가 현재 받아들일 수 있는 모든 대체 방안</strong>이라는 것을 알게 됩니다.</p><h2 id="_2-jtbd는-사용자-페르소나-기능-목록과-무엇이-다른가" tabindex="-1">2. JTBD는 사용자 페르소나, 기능 목록과 무엇이 다른가 <a class="header-anchor" href="#_2-jtbd는-사용자-페르소나-기능-목록과-무엇이-다른가" aria-label="Permalink to “2. JTBD는 사용자 페르소나, 기능 목록과 무엇이 다른가”">​</a></h2><p>많은 초보자는 수요 분석을 시작할 때 먼저 사용자 페르소나를 씁니다. 25세, 여성, 1선 도시, 직장인, 효율 도구를 좋아하고 새 제품을 시도할 의향이 있음. 이런 정보가 완전히 쓸모없다고 할 수는 없지만, 보통 <strong>한 사람이 왜 이 순간 행동을 취하는지 설명하기에는 부족합니다.</strong></p><p>JTBD는 아래 질문에 더 관심이 있습니다.</p><ul><li>그는 어떤 장면에서 해결책을 찾기로 결정했는가</li><li>당시 정확히 무엇에 막혔는가</li><li>무엇을 다음 단계로 밀고 싶었는가</li><li>지금은 어떤 서툰 방법으로 버티고 있는가</li><li>일이 잘 해결된다면 어떤 결과가 &quot;가치 있었다&quot;고 느끼게 하는가</li></ul><p>즉, <strong>사용자 페르소나는 &quot;이 사람이 대략 누구인가&quot;에 가깝고, JTBD는 &quot;이 사람이 지금 정확히 무엇을 완료하고 싶은가&quot;에 가깝습니다.</strong></p><p>마찬가지로 기능 목록도 사람을 쉽게 빗나가게 합니다. 사용자가 &quot;Word로 내보내고 싶어요&quot;, &quot;AI 문장 개선이 있으면 좋겠어요&quot;, &quot;음성 입력이 필요해요&quot;라고 말할 수 있습니다. 하지만 이것들은 모두 표면 표현입니다. JTBD는 계속 아래로 묻습니다.</p><ul><li>왜 지금 PDF가 아니라 Word 내보내기가 필요한가?</li><li>문장을 고치고 싶은 이유는 문체가 나빠서인가, 아니면 대상에 맞게 바꿔야 해서인가?</li><li>음성 입력이 필요한 이유는 타이핑이 귀찮아서인가, 아니면 자주 걸으면서, 운전하면서, 회의 직후에 바로 기록해야 해서인가?</li></ul><p>많은 경우 <strong>기능은 job의 임시 번역일 뿐</strong>입니다. 기능만 수집하면 &quot;사용자가 말하는 것을 전부 쌓는&quot; 제품이 되기 쉽습니다. 뒤에 있는 job을 볼 수 있어야 진짜로 쓰기 편하고 경쟁력 있는 솔루션을 만들 가능성이 커집니다.</p><h2 id="_3-제로-베이스도-이해할-수-있는-예시" tabindex="-1">3. 제로 베이스도 이해할 수 있는 예시 <a class="header-anchor" href="#_3-제로-베이스도-이해할-수-있는-예시" aria-label="Permalink to “3. 제로 베이스도 이해할 수 있는 예시”">​</a></h2><p>복잡한 AI 제품을 서둘러 생각하지 말고, 먼저 생활 속 예시에서 시작해 봅시다.</p><p>어떤 사람이 아침에 나가기 전 늘 아침을 먹을 시간이 부족해서 지하철역 입구에서 샌드위치와 커피를 자주 산다고 가정해 봅시다. 표면적으로 그는 &quot;아침 식사&quot;를 구매합니다. 하지만 JTBD로 보면 그가 진짜 완료하고 싶은 일은 이럴 수 있습니다.</p><ul><li>바쁜 아침에 가장 머리를 덜 쓰는 방식으로 한 끼를 해결한다.</li><li>회사에 도착하기 전에 배고파 불안해지지 않도록 한다.</li><li>아침 식사 때문에 출근 리듬을 망치지 않는다.</li></ul><p>이때 사용자가 고용한 것은 &quot;어떤 고정 브랜드의 샌드위치&quot;가 아니라, 아침을 순조롭게 앞으로 밀어 주는 해결책입니다. 옆 편의점이 더 빠르고, 더 가깝고, 더 안정적이면 그는 원래 선택을 바로 바꿀 수 있습니다.</p><p>이 논리를 AI 제품으로 옮기면 더 분명해집니다.</p><p>예를 들어 &quot;AI 회의록 도구&quot;를 만들고 싶다고 합시다. 기능 층위에만 머물면 쉽게 이런 생각을 하게 됩니다.</p><ul><li>오디오 업로드를 지원할까</li><li>화자 분리를 붙일까</li><li>Markdown 내보내기를 할까</li><li>할 일을 자동 생성할까</li></ul><p>이것들은 모두 틀리지 않지만 충분하지 않습니다. JTBD로 한 층 더 물으면 사용자가 진짜 완료하고 싶은 것은 다음일 수 있습니다.</p><ul><li>회의 후 10분 안에 참석하지 못한 사람에게 논의 결과를 동기화하고 싶다.</li><li>할 일, 담당자, 마감일을 깔끔하게 뽑아 팀이 기억에 의존해 협업하지 않게 하고 싶다.</li><li>회의 내용을 반복 정리하는 시간을 줄이고, 에너지를 의사결정과 추진에 남기고 싶다.</li></ul><p>job이 명확해지면 많은 기능의 우선순위가 자동으로 떠오릅니다. 첫 버전에서 가장 중요한 것은 &quot;12가지 내보내기 형식 지원&quot;이 아니라 다음일 수 있습니다.</p><ul><li>회의록 구조가 충분히 명확해야 한다.</li><li>할 일 추출이 안정적이어야 한다.</li><li>공유 링크가 편리해야 한다.</li><li>출력 결과를 팀에 바로 전달할 수 있을 만큼 믿을 수 있어야 한다.</li></ul><p>이것이 JTBD의 가치입니다. <strong>&quot;어떤 능력을 쌓을까&quot;에서 &quot;사용자가 어떤 진전을 이루도록 도울까&quot;로 되돌려 줍니다.</strong></p><h2 id="_4-쓰기-좋은-jtbd-템플릿" tabindex="-1">4. 쓰기 좋은 JTBD 템플릿 <a class="header-anchor" href="#_4-쓰기-좋은-jtbd-템플릿" aria-label="Permalink to “4. 쓰기 좋은 JTBD 템플릿”">​</a></h2><p>제로 베이스라면 JTBD를 너무 학술적으로 생각하지 않아도 됩니다. 가장 실용적인 5개 요소만 잡으면 충분합니다.</p><h3 id="_4-1-장면" tabindex="-1">4.1 장면 <a class="header-anchor" href="#_4-1-장면" aria-label="Permalink to “4.1 장면”">​</a></h3><p>사용자는 어떤 순간, 어떤 환경에서 이 제품을 떠올리는가?</p><ul><li>회의가 끝난 뒤인가</li><li>상사가 갑자기 자료를 요구할 때인가</li><li>밤에 이력서를 제출하려고 준비할 때인가</li><li>월말에 돈이 또 부족하다는 것을 발견했을 때인가</li></ul><p><strong>장면이 없는 수요는 보통 아직 충분히 진짜가 아닙니다.</strong></p><h3 id="_4-2-트리거" tabindex="-1">4.2 트리거 <a class="header-anchor" href="#_4-2-트리거" aria-label="Permalink to “4.2 트리거”">​</a></h3><p>무엇이 그를 즉시 해결책을 찾게 만들었는가?</p><ul><li>긴 문서에 눌려 어디서부터 봐야 할지 모른다.</li><li>내일 제출해야 하는 자료가 있는데 오늘서야 형식이 엉망이라는 것을 발견했다.</li><li>방금 리더에게 진행 상황을 추궁당했고, 자신이 정리를 제대로 해 두지 않았다는 것을 깨달았다.</li><li>기록을 꾸준히 하고 싶지만 손글씨, 복사, 정리가 모두 너무 번거롭다.</li></ul><p>트리거에는 보통 감정이 함께 있습니다. 이 감정은 매우 중요합니다. 왜냐하면 사용자가 왜 바로 이 순간 행동하게 되는지를 결정하기 때문입니다.</p><h3 id="_4-3-완료하고-싶은-진전" tabindex="-1">4.3 완료하고 싶은 진전 <a class="header-anchor" href="#_4-3-완료하고-싶은-진전" aria-label="Permalink to “4.3 완료하고 싶은 진전”">​</a></h3><p>그는 단지 &quot;동작 하나&quot;를 하고 싶은 것이 아니라, 자신을 어떤 새로운 상태로 밀어 넣고 싶은가?</p><ul><li>혼란에서 명확함으로</li><li>불안에서 안심으로</li><li>미룸에서 시작으로</li><li>비효율에서 매끄러움으로</li><li>설명하지 못함에서 바로 전달 가능함으로</li></ul><p>이 단계에서 &quot;진전&quot;이라는 단어가 매우 중요합니다. 많은 사람이 진짜로 사는 것은 도구가 아니라 <strong>상태 변화</strong>이기 때문입니다.</p><h3 id="_4-4-현재-대체-방안" tabindex="-1">4.4 현재 대체 방안 <a class="header-anchor" href="#_4-4-현재-대체-방안" aria-label="Permalink to “4.4 현재 대체 방안”">​</a></h3><p>당신의 제품이 없을 때 그는 지금 어떻게 하는가?</p><ul><li>수동 복사/붙여넣기</li><li>Excel이나 메모장으로 억지로 버티기</li><li>동료에게 부탁하기</li><li>미뤄 두기</li><li>여러 도구 사이를 왔다 갔다 하기</li></ul><p>대체 방안이 누구인지가 곧 당신의 실제 경쟁 환경입니다.</p><h3 id="_4-5-성공-기준" tabindex="-1">4.5 성공 기준 <a class="header-anchor" href="#_4-5-성공-기준" aria-label="Permalink to “4.5 성공 기준”">​</a></h3><p>어떤 상태가 되어야 일이 진짜 해결되었다고 볼 수 있는가?</p><ul><li>10분 안에 공유 가능한 결과를 얻는다.</li><li>크게 다시 고치지 않아도 다른 사람에게 보낼 수 있다.</li><li>누락, 오류, 잊어버림이 쉽게 생기지 않는다.</li><li>처음 써도 다음에 무엇을 해야 하는지 안다.</li></ul><p>&quot;사용자가 어떻게 가치 있다고 판단하는지&quot;조차 말하지 못한다면, 이 방향은 아직 충분히 수렴되지 않았을 가능성이 큽니다.</p><p><a id="jtbd-formula"></a></p><h2 id="_5-바로-적용할-수-있는-한-문장-공식" tabindex="-1"><a href="#top-jtbd">5. 바로 적용할 수 있는 한 문장 공식</a> <a class="header-anchor" href="#_5-바로-적용할-수-있는-한-문장-공식" aria-label="Permalink to “5. 바로 적용할 수 있는 한 문장 공식”">​</a></h2><p>제품 방향을 정리하고 싶을 때는 먼저 이 매우 실용적인 문장 형식을 사용할 수 있습니다.</p><blockquote><p>__________ 할 때, 나는 __________ 하고 싶다. 그래야 __________ 할 수 있다.<br> 지금은 __________ 방식으로 겨우 이 일을 해내고 있다.</p></blockquote><p>예를 들면:</p><blockquote><p>정보량이 많은 프로젝트 회의가 끝났을 때, 나는 할 일, 담당자, 마감일이 포함된 회의록을 빠르게 얻고 싶다. 그래야 팀에 바로 동기화하고 실행을 추진할 수 있다.<br> 지금은 기억을 더듬고, 채팅 기록을 뒤지고, 손으로 정리하는 방식으로 겨우 이 일을 해내고 있다.</p></blockquote><p>또 다른 예:</p><blockquote><p>새로운 직무에 지원하려고 할 때, 나는 기존 경험을 해당 직무에 더 맞는 표현으로 빠르게 고치고 싶다. 그래야 더 확신 있게 그럴듯한 이력서를 제출할 수 있다.<br> 지금은 예전 이력서를 반복해서 복사하고, 문구를 손으로 고치고, 마지막에는 점점 더 확신이 없어지는 방식으로 버티고 있다.</p></blockquote><p>이 한 문장을 이 정도로 명확하게 쓸 수 있다면, 뒤의 페이지 설계, 프롬프트 설계, 기능 우선순위 판단이 훨씬 쉬워집니다.</p><h2 id="_6-ai-제품을-만들-때-특히-봐야-할-job의-세-층" tabindex="-1">6. AI 제품을 만들 때 특히 봐야 할 job의 세 층 <a class="header-anchor" href="#_6-ai-제품을-만들-때-특히-봐야-할-job의-세-층" aria-label="Permalink to “6. AI 제품을 만들 때 특히 봐야 할 job의 세 층”">​</a></h2><p>많은 AI 제품은 기능 시연 때는 강력해 보이지만 실제 출시 후 사용자를 붙잡지 못합니다. 흔한 이유는 표면 동작만 해결하고 더 깊은 job을 해결하지 못했기 때문입니다.</p><p>하나의 job을 대략 세 층으로 나누어 볼 수 있습니다.</p><h3 id="_6-1-기능-층" tabindex="-1">6.1 기능 층 <a class="header-anchor" href="#_6-1-기능-층" aria-label="Permalink to “6.1 기능 층”">​</a></h3><p>가장 표면적인 과제는 무엇인가?</p><ul><li>문서 요약</li><li>문구 재작성</li><li>할 일 추출</li><li>이미지 생성</li></ul><p>사용자가 말로 가장 쉽게 말하는 층입니다.</p><h3 id="_6-2-감정-층" tabindex="-1">6.2 감정 층 <a class="header-anchor" href="#_6-2-감정-층" aria-label="Permalink to “6.2 감정 층”">​</a></h3><p>사용자는 어떤 불편한 감정을 줄이거나 어떤 느낌을 얻고 싶은가?</p><ul><li>덜 당황하고 싶다.</li><li>덜 비전문적으로 보이고 싶다.</li><li>매번 처음부터 시작하고 싶지 않다.</li><li>더 통제감을 갖고 싶다.</li></ul><p>많은 지불 의향은 실제로 감정 층과 큰 관련이 있습니다.</p><h3 id="_6-3-사회적-층" tabindex="-1">6.3 사회적 층 <a class="header-anchor" href="#_6-3-사회적-층" aria-label="Permalink to “6.3 사회적 층”">​</a></h3><p>사용자는 다른 사람 눈에 어떤 사람으로 보이고 싶은가?</p><ul><li>더 믿음직해 보이고 싶다.</li><li>팀에서 더 조직적인 사람으로 보이고 싶다.</li><li>고객 앞에서 더 전문적으로 보이고 싶다.</li><li>소셜 플랫폼에서 더 잘 표현하는 사람으로 보이고 싶다.</li></ul><p>기능 층만 만들면 제품은 쉽게 대체됩니다. 감정 층과 사회적 층까지 이해하면 진짜 끈적한 가치를 찾기 쉬워집니다.</p><h2 id="_7-jtbd로-제품-방향을-거꾸로-걸러내기" tabindex="-1">7. JTBD로 제품 방향을 거꾸로 걸러내기 <a class="header-anchor" href="#_7-jtbd로-제품-방향을-거꾸로-걸러내기" aria-label="Permalink to “7. JTBD로 제품 방향을 거꾸로 걸러내기”">​</a></h2><p>이미 제품이 있는 것이 아니라 손에 3~5개의 아이디어가 있고 무엇을 해야 할지 모르겠다면, JTBD는 선별에 매우 적합합니다.</p><p>각 아이디어를 두고 다음 5가지 질문을 해 보세요.</p><ol><li>이 아이디어가 대응하는 장면이 충분히 구체적인가?</li><li>사용자는 지금 이미 어떤 서툰 방식으로 해결하고 있는가?</li><li>이 job의 고통감이 충분히 강하거나 충분히 자주 발생하는가?</li><li>내가 잘 만들면 사용자가 &quot;상태가 좋아졌다&quot;고 분명히 느낄까?</li><li>첫 버전은 이 job의 핵심 한 단계만 중심으로 작지만 유용하게 만들 수 있을까?</li></ol><p>어떤 방향을 끝까지 말해도 &quot;느낌상 재미있다&quot; 정도밖에 말하지 못하고 트리거, 대체 방안, 성공 기준을 말하지 못한다면, 그것은 아직 성숙한 방향이 아니라 흐릿한 영감일 가능성이 큽니다.</p><h2 id="_8-사용자-인터뷰에-바로-가져갈-수-있는-질문" tabindex="-1">8. 사용자 인터뷰에 바로 가져갈 수 있는 질문 <a class="header-anchor" href="#_8-사용자-인터뷰에-바로-가져갈-수-있는-질문" aria-label="Permalink to “8. 사용자 인터뷰에 바로 가져갈 수 있는 질문”">​</a></h2><p>많은 사람이 조사를 시작하면 &quot;어떤 기능을 원하세요?&quot;라고 묻습니다. 이런 질문은 표면적인 답을 얻기 쉽습니다.</p><p>JTBD에는 아래 질문들이 더 적합합니다.</p><ul><li>최근에 이 문제를 만난 것은 언제인가요?</li><li>그때 무엇을 하고 있었고, 왜 막혔나요?</li><li>결국 어떻게 해결했나요?</li><li>이 과정에서 가장 짜증 나고, 느리고, 불안한 지점은 무엇이었나요?</li><li>도구가 도와준다면 어떤 결과가 정말 유용하다고 느껴질까요?</li><li>어떤 대체 방법을 써 봤나요? 왜 충분하지 않았나요?</li></ul><p>이런 질문 방식의 장점은 대화를 상상 속 취향이 아니라 실제 경험으로 되돌린다는 점입니다.</p><h2 id="_9-ai로-jtbd-분해하기" tabindex="-1">9. AI로 JTBD 분해하기 <a class="header-anchor" href="#_9-ai로-jtbd-분해하기" aria-label="Permalink to “9. AI로 JTBD 분해하기”">​</a></h2><p>JTBD 자체는 AI가 발명한 것이 아니지만, AI는 JTBD를 정리하고 추출하는 데 매우 적합합니다.</p><p>예를 들어 사용자 피드백 5~10개를 이미 모았다면, 그것을 모델에게 던져 아래 구조로 요약하게 할 수 있습니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>제품 리서치 조수 역할을 해 줘.</span></span>
<span class="line"><span>사용자 원문을 줄 테니 먼저 기능 제안을 하지 말고,</span></span>
<span class="line"><span>Jobs to Be Done 프레임워크에 따라 정리해 줘.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 사용자는 어떤 장면에 있는가</span></span>
<span class="line"><span>2. 사용자가 행동하게 된 트리거는 무엇인가</span></span>
<span class="line"><span>3. 사용자가 진짜 완료하고 싶은 진전은 무엇인가</span></span>
<span class="line"><span>4. 현재 대체 방안은 무엇인가</span></span>
<span class="line"><span>5. 사용자가 가장 중요하게 보는 성공 기준은 무엇인가</span></span>
<span class="line"><span>6. 이 피드백들에서 반복해서 등장하는 감정 단어는 무엇인가</span></span>
<span class="line"><span></span></span>
<span class="line"><span>마지막으로 이 내용을 검증 우선순위가 높은 JTBD 가설 3개로 정리해 줘.</span></span></code></pre></div><p>이미 아이디어가 있다면 AI에게 1차 수렴을 도와달라고 할 수도 있습니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[제품 아이디어]를 만들고 싶어.</span></span>
<span class="line"><span>기능 목록을 바로 주지 말고, Jobs to Be Done 방법으로 분석해 줘.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 이 제품이 섬길 수 있는 구체적인 장면은 무엇인가</span></span>
<span class="line"><span>2. 각 장면에서 사용자가 완료하고 싶은 핵심 job은 무엇인가</span></span>
<span class="line"><span>3. 기존 대체 방안은 무엇인가</span></span>
<span class="line"><span>4. 어떤 job이 MVP 출발점으로 가장 적합한가, 왜 그런가</span></span>
<span class="line"><span>5. 마지막으로 추천하는 job을 명확한 JTBD 문장 한 개로 작성해 줘</span></span></code></pre></div><p>이렇게 하면 처음부터 AI가 &quot;기능 50개 브레인스토밍&quot;으로 끌고 가지 않고, 먼저 방향을 명확하게 말하게 할 수 있습니다.</p><h2 id="_10-초보자가-가장-흔히-하는-4가지-오해" tabindex="-1">10. 초보자가 가장 흔히 하는 4가지 오해 <a class="header-anchor" href="#_10-초보자가-가장-흔히-하는-4가지-오해" aria-label="Permalink to “10. 초보자가 가장 흔히 하는 4가지 오해”">​</a></h2><h3 id="_10-1-job을-기능명으로-쓰기" tabindex="-1">10.1 job을 기능명으로 쓰기 <a class="header-anchor" href="#_10-1-job을-기능명으로-쓰기" aria-label="Permalink to “10.1 job을 기능명으로 쓰기”">​</a></h3><p>&quot;AI 요약&quot;, &quot;지능형 분류&quot;, &quot;자동 생성&quot;은 모두 job이 아닙니다. 그것들은 가능한 구현 방식일 뿐입니다.</p><h3 id="_10-2-사람군을-너무-넓게-쓰기" tabindex="-1">10.2 사람군을 너무 넓게 쓰기 <a class="header-anchor" href="#_10-2-사람군을-너무-넓게-쓰기" aria-label="Permalink to “10.2 사람군을 너무 넓게 쓰기”">​</a></h3><p>&quot;모든 직장인&quot;, &quot;모든 학생&quot;, &quot;모든 창업자&quot;는 보통 너무 넓습니다. 넓을수록 실제 장면을 보기 어려워집니다.</p><h3 id="_10-3-사용자가-말하는-것만-듣고-실제-행동은-보지-않기" tabindex="-1">10.3 사용자가 말하는 것만 듣고, 실제 행동은 보지 않기 <a class="header-anchor" href="#_10-3-사용자가-말하는-것만-듣고-실제-행동은-보지-않기" aria-label="Permalink to “10.3 사용자가 말하는 것만 듣고, 실제 행동은 보지 않기”">​</a></h3><p>사용자는 자신이 원하는 것을 설명할 수 있지만, 진짜 우선순위는 지금 어떻게 문제를 임시로 해결하고 있는지에 숨어 있는 경우가 많습니다.</p><h3 id="_10-4-처음부터-완전한-플랫폼을-만들려고-하기" tabindex="-1">10.4 처음부터 완전한 플랫폼을 만들려고 하기 <a class="header-anchor" href="#_10-4-처음부터-완전한-플랫폼을-만들려고-하기" aria-label="Permalink to “10.4 처음부터 완전한 플랫폼을 만들려고 하기”">​</a></h3><p>JTBD를 올바르게 여는 방식은 보통 &quot;모든 것을 해결하는 큰 플랫폼을 만들겠다&quot;가 아닙니다. 먼저 한 장면에서 가장 중요한 한 단계를 겨냥하고, 그것을 매우 매끄럽게 만드는 것입니다.</p><h2 id="_11-정리" tabindex="-1">11. 정리 <a class="header-anchor" href="#_11-정리" aria-label="Permalink to “11. 정리”">​</a></h2><p>Jobs to Be Done의 가장 가치 있는 점은 새로운 용어를 하나 주는 것이 아니라, 관찰 관점을 바꿔 준다는 것입니다. <strong>제품 기능만 바라보지 말고, 사용자가 어떤 일을 다음 단계로 밀고 싶어 하는지 바라보세요.</strong></p><p>다음 질문을 반복해 묻기 시작하면:</p><ul><li>사용자는 어떤 장면에서 이 제품을 고용하는가</li><li>정확히 어디에서 막혔는가</li><li>지금은 어떤 방식으로 버티고 있는가</li><li>일이 해결되면 상태가 어떻게 변하는가</li></ul><p>원래 흐릿했던 많은 아이디어가 갑자기 선명해지고, 원래 화려해 보였던 많은 기능이 갑자기 그다지 중요하지 않게 됩니다.</p><p>제품을 만들 때, 특히 AI 제품을 만들 때 가장 위험한 것은 처음부터 능력 시연에 빠지는 것입니다. JTBD는 당신의 주의를 진짜 중요한 곳으로 되돌립니다. <strong>사용자가 왜 당신을 필요로 하는가, 그리고 당신은 정확히 어떤 진전을 완성하도록 돕는가.</strong></p><p><a id="jtbd-ai"></a></p><h2 id="_12-ai로-jtbd를-실천하는-방법" tabindex="-1"><a href="#top-jtbd">12. AI로 JTBD를 실천하는 방법</a> <a class="header-anchor" href="#_12-ai로-jtbd를-실천하는-방법" aria-label="Permalink to “12. AI로 JTBD를 실천하는 방법”">​</a></h2><p>JTBD는 AI가 발명한 것이 아니지만, AI는 이 방법 안에서 리서치 조수, 정리 조수, 대조 조수 역할을 하기에 매우 적합합니다. 핵심은 <strong>AI가 사용자를 상상해 대신 결론 내리게 하지 말고, 정리와 확장을 돕게 하는 것</strong>입니다.</p><p>다음처럼 사용할 수 있습니다.</p><h3 id="_12-1-ai에게-흐릿한-아이디어를-jtbd-가설로-바꾸게-하기" tabindex="-1">12.1 AI에게 흐릿한 아이디어를 JTBD 가설로 바꾸게 하기 <a class="header-anchor" href="#_12-1-ai에게-흐릿한-아이디어를-jtbd-가설로-바꾸게-하기" aria-label="Permalink to “12.1 AI에게 흐릿한 아이디어를 JTBD 가설로 바꾸게 하기”">​</a></h3><p>머릿속에 &quot;대학생이 인턴십을 찾도록 돕는 도구를 만들고 싶다&quot;처럼 흐릿한 설명만 있다면, 먼저 AI에게 여러 가능한 job으로 나눠 보게 할 수 있습니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>지금 흐릿한 제품 아이디어가 있어: [아이디어]</span></span>
<span class="line"><span>기능 목록을 바로 주지 말고, Jobs to Be Done 방식으로 분석해 줘.</span></span>
<span class="line"><span>1. 어떤 구체적인 장면에 대응할 수 있는가</span></span>
<span class="line"><span>2. 각 장면에서 사용자가 진짜 완료하고 싶은 진전은 무엇인가</span></span>
<span class="line"><span>3. 현재 대체 방안은 무엇일 수 있는가</span></span>
<span class="line"><span>4. 어떤 job이 MVP로 먼저 만들기 가장 적합한가</span></span>
<span class="line"><span>마지막에는 각 job을 명확한 JTBD 문장으로 써 줘.</span></span></code></pre></div><p>아주 초보적인 입력도 괜찮습니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>대학생이 인턴십을 찾는 것을 돕는 무언가를 만들고 싶어.</span></span>
<span class="line"><span>나도 아직 구체적으로 뭘 만들지 잘 모르겠어. 사용자가 정확히 어떤 일을 완료하고 싶은지 같이 생각해 줘.</span></span></code></pre></div><p>AI가 주는 유용한 출력은 이렇게 생겼을 수 있습니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>가능한 JTBD 방향:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 처음 인턴십 지원을 준비할 때, 먼저 무엇을 준비해야 하는지 빠르게 알고 싶다.</span></span>
<span class="line"><span>그래야 정보가 혼란스러워 계속 지원을 미루지 않을 수 있다.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 어떤 인턴십 공고를 봤을 때, 내가 지원할 가치가 있는지 빠르게 판단하고 싶다.</span></span>
<span class="line"><span>그래야 맞지 않는 공고에 너무 많은 시간을 낭비하지 않을 수 있다.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. 지원을 시작할 때, 기존 이력서를 직무에 더 맞는 버전으로 바꾸고 싶다.</span></span>
<span class="line"><span>그래야 더 빨리 지원을 완료하고 통과율을 높일 수 있다.</span></span></code></pre></div><p>이 출력의 가치는 매우 넓었던 생각 하나를 실제 장면에 가까운 여러 방향으로 나눈다는 데 있습니다.</p><h3 id="_12-2-ai에게-인터뷰-원문을-정리하게-하기" tabindex="-1">12.2 AI에게 인터뷰 원문을 정리하게 하기 <a class="header-anchor" href="#_12-2-ai에게-인터뷰-원문을-정리하게-하기" aria-label="Permalink to “12.2 AI에게 인터뷰 원문을 정리하게 하기”">​</a></h3><p>사용자 인터뷰를 몇 번 했다면, 인터뷰 기록을 AI에게 주고 반복해서 등장하는 장면, 트리거, 대체 방안, 성공 기준을 추출하게 할 수 있습니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>아래는 사용자 5명의 인터뷰 원문이야.</span></span>
<span class="line"><span>먼저 해결책을 주지 말고, JTBD 프레임워크에 따라 정리해 줘.</span></span>
<span class="line"><span>1. 사용자는 어떤 장면에 있는가</span></span>
<span class="line"><span>2. 사용자가 행동하게 된 트리거는 무엇인가</span></span>
<span class="line"><span>3. 사용자가 진짜 완료하고 싶은 진전은 무엇인가</span></span>
<span class="line"><span>4. 현재 대체 방안은 무엇인가</span></span>
<span class="line"><span>5. 사용자가 가장 중요하게 여기는 성공 기준은 무엇인가</span></span>
<span class="line"><span>6. 여러 사용자에게 반복해서 나타난 정보는 무엇인가</span></span>
<span class="line"><span>마지막에는 검증 우선순위가 높은 JTBD 가설 3개로 정리해 줘.</span></span></code></pre></div><p>아주 간단한 초보자 입력도 이렇게 쓸 수 있습니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>3명에게 물어봤는데, 대략 이렇게 말했어.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 인턴십에 지원할 때마다 이력서를 다시 고쳐야 해서 너무 귀찮다.</span></span>
<span class="line"><span>2. 사실 가장 두려운 건 내가 잘 썼는지 모르겠다는 것이다.</span></span>
<span class="line"><span>3. 지금은 선배에게 먼저 봐 달라고 하는데, 매번 부탁하기가 미안하다.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>그들이 진짜 완료하고 싶은 일이 무엇인지 정리해 줘.</span></span></code></pre></div><p>AI는 이렇게 출력할 수 있습니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>정리 결과:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 공통 장면: 인턴십 지원 준비 전, 이력서를 처리해야 함</span></span>
<span class="line"><span>- 공통 어려움: &quot;충분히 좋은&quot; 상태까지 수정했는지 판단하지 못함</span></span>
<span class="line"><span>- 현재 대체 방안: 선배에게 봐 달라고 부탁하거나 직접 반복 수정</span></span>
<span class="line"><span>- 가능한 JTBD:</span></span>
<span class="line"><span>  인턴십 지원을 준비할 때, 이력서가 이미 지원 가능한 수준인지 더 빨리 판단하고 싶다.</span></span>
<span class="line"><span>  그래야 &quot;조금만 더 고쳐 보자&quot;에 계속 막혀 지원을 미루지 않을 수 있다.</span></span></code></pre></div><p>이 출력은 유용합니다. 흩어진 원문 속에서 더 &quot;수요&quot;에 가까운 것을 뽑아 주기 때문입니다.</p><h3 id="_12-3-ai에게-가벼운-웹-조사를-한-번-맡기기" tabindex="-1">12.3 AI에게 가벼운 웹 조사를 한 번 맡기기 <a class="header-anchor" href="#_12-3-ai에게-가벼운-웹-조사를-한-번-맡기기" aria-label="Permalink to “12.3 AI에게 가벼운 웹 조사를 한 번 맡기기”">​</a></h3><p>대규모 인터뷰를 시작하기 전, AI에게 아주 가벼운 외부 정보 스캔을 맡길 수 있습니다. 예를 들면 다음입니다.</p><ul><li>공개 포럼이나 커뮤니티에서 사람들이 이 문제를 어떻게 불평하는가</li><li>시장에 이미 있는 제품들은 주로 어느 층의 문제를 해결하는가</li><li>사용자가 가장 흔히 쓰는 대체 방안은 무엇인가</li><li>흔한 평가에서 사람들이 가장 만족하고 불만족하는 지점은 무엇인가</li></ul><p>이 조사는 실제 사용자 인터뷰를 대체할 수 없지만, Discover 단계의 워밍업으로 매우 적합하며 먼저 문제 지도를 만드는 데 도움을 줍니다.</p><p>간단한 입력 예시는 다음입니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>조사해 줘.</span></span>
<span class="line"><span>&quot;대학생이 이력서를 고치고 인턴십에 지원할 때 가장 흔히 겪는 고통은 무엇인가?&quot;</span></span>
<span class="line"><span>공개 포럼, 경험 글, 취업 커뮤니티에서 사람들이 직접 말한 내용을 우선 봐 줘.</span></span>
<span class="line"><span>가장 흔한 문제 5개로 정리해 줘.</span></span></code></pre></div><p>AI는 이렇게 출력할 수 있습니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>흔한 고통 정리:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 이력서에 무엇을 써야 할지 모르고 경험이 너무 적다.</span></span>
<span class="line"><span>2. 직무마다 어떻게 다르게 수정해야 할지 모른다.</span></span>
<span class="line"><span>3. 여러 번 고쳤지만 충분히 좋은지 계속 확신하지 못한다.</span></span>
<span class="line"><span>4. 믿을 만한 사람에게 봐 달라고 하기 어렵다.</span></span>
<span class="line"><span>5. 지원 절차가 복잡해 쉽게 미룬다.</span></span></code></pre></div><p>이런 출력은 최종 결론으로 삼을 수는 없지만, 어떤 문제를 먼저 인터뷰할지 결정하는 데 적합합니다.</p><h3 id="_12-4-ai에게-반대편-역할을-맡기기" tabindex="-1">12.4 AI에게 &quot;반대편&quot; 역할을 맡기기 <a class="header-anchor" href="#_12-4-ai에게-반대편-역할을-맡기기" aria-label="Permalink to “12.4 AI에게 &quot;반대편&quot; 역할을 맡기기”">​</a></h3><p>많은 경우 우리는 자기 아이디어에 감정적으로 너무 붙어 있습니다. AI에게 일부러 비판하는 사람 역할을 맡겨 문제를 더 명확하게 말하도록 압박할 수 있습니다.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>매우 엄격한 제품 리서치 컨설턴트 역할을 해 줘.</span></span>
<span class="line"><span>아래는 내 JTBD 가설이야: [가설]</span></span>
<span class="line"><span>다음 관점에서 비판해 줘.</span></span>
<span class="line"><span>1. 이 장면이 너무 넓은가</span></span>
<span class="line"><span>2. 이 job이 진짜 진전이 아니라 기능으로 쓰였는가</span></span>
<span class="line"><span>3. 대체 방안이 너무 약한가</span></span>
<span class="line"><span>4. 성공 기준이 충분히 명확하지 않은가</span></span>
<span class="line"><span>5. 이 가설에서 가장 먼저 검증해야 할 위험은 무엇인가</span></span></code></pre></div><p>이렇게 하면 당신이 수요를 보고 있는지, 아니면 좋아하는 솔루션만 보고 있는지 더 빨리 발견할 수 있습니다.</p><h2 id="📚-assignments" tabindex="-1">📚 Assignments <a class="header-anchor" href="#📚-assignments" aria-label="Permalink to “📚 Assignments”">​</a></h2><p>위 내용을 바탕으로 다음 과제를 완료하세요.</p><ol><li>최근 만들고 싶은 제품 아이디어 하나를 고르고, JTBD 공식 한 문장으로 명확하게 쓰세요.</li><li>이 아이디어에 5개 요소를 보충하세요: 장면, 트리거, 진전, 대체 방안, 성공 기준.</li><li>잠재 사용자 3명을 찾아 최소 한 번은 &quot;최근에 이 문제를 만난 것은 언제였나요?&quot;라고 물어보세요.</li><li>인터뷰 원문을 AI에게 주고 검증 우선순위가 높은 JTBD 가설 3개로 정리하세요.</li></ol><h2 id="더-읽어-보기" tabindex="-1">더 읽어 보기 <a class="header-anchor" href="#더-읽어-보기" aria-label="Permalink to “더 읽어 보기”">​</a></h2><ul><li><a href="https://www.christenseninstitute.org/theory/jobs-to-be-done/" target="_blank" rel="noreferrer">Christensen Institute: Jobs to Be Done</a></li><li><a href="https://online.hbs.edu/blog/post/jobs-to-be-done" target="_blank" rel="noreferrer">Harvard Business School Online: What Is Jobs to Be Done?</a></li><li><a href="https://www.intercom.com/blog/jobs-to-be-done-framework/" target="_blank" rel="noreferrer">Intercom: Jobs-to-be-Done: A framework for customer needs</a></li><li><a href="https://www.mural.co/blog/jobs-to-be-done-framework" target="_blank" rel="noreferrer">Mural: Jobs to Be Done framework guide</a></li></ul>`,148))])}}});export{g as __pageData,k as default};
